import numpy as np
from collections import Counter, deque
x=np.load('source_pixels.npz')['rgb']
def comps(m):
 h,w=m.shape; seen=np.zeros_like(m,bool); out=[]
 for y,x0 in zip(*np.where(m & ~seen)):
  if seen[y,x0]: continue
  q=[(y,x0)];seen[y,x0]=1; pts=[]
